package com.travelbird.trip.service;
import com.travelbird.ai.entity.*;import com.travelbird.global.error.*;import com.travelbird.region.repository.SigunguMasterRepository;import com.travelbird.trip.entity.*;import com.travelbird.trip.repository.*;import java.time.*;import java.util.*;import org.springframework.stereotype.Service;
@Service public class TripAiRouteService{private final TripRepository trips;private final TripPlaceRepository tripPlaces;private final SigunguMasterRepository regions;private final Clock clock;public TripAiRouteService(TripRepository t,TripPlaceRepository tripPlaces,SigunguMasterRepository r,Clock c){trips=t;this.tripPlaces=tripPlaces;regions=r;clock=c;}public record Result(Trip trip,String type,LocalDateTime at){}public Result apply(AiTripPreview p,Long uid){var job=p.getJob();var at=LocalDateTime.now(clock);Trip trip;String type;if(job.getTargetTripId()==null){var region=regions.findBySigunguCode(job.getRegionCode()).orElseThrow(()->new BusinessException(ErrorCode.REGION_REQUIRED));trip=Trip.createManual(job.getUser(),region,job.getStartDate(),job.getEndDate(),job.getCompanionType(),new LinkedHashSet<>(new com.travelbird.ai.service.RecommendationSnapshotCodec(new com.fasterxml.jackson.databind.ObjectMapper()).read(job).themes()),job.getPace(),at);trip.updateBasic(p.getTripTitle(),true,p.getSummary(),true,null,false,null,false,null,false,null,false);trip.markAiSource();type="CREATED_NEW_TRIP";}else{trip=trips.findByIdForUpdate(job.getTargetTripId()).orElseThrow(()->new BusinessException(ErrorCode.TRIP_NOT_FOUND));if(!trip.ownedBy(uid))throw new BusinessException(ErrorCode.TRIP_ACCESS_DENIED);trip.ensureMutable();if(trips.existsPublishedPost(trip.getId()))throw new BusinessException(ErrorCode.TRIP_ROUTE_LOCKED_BY_PUBLISHED_POST);for(var day:trip.getDays())tripPlaces.stageOrders(trip.getId(),day.getDayNumber());type="UPDATED_EXISTING_TRIP";}trip.applyAiPreview(p.getDays());return new Result(trips.save(trip),type,at);}}
